START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261024014854_AddProductReviews') THEN
    CREATE TABLE "ProductReviews" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "ProductId" bigint NOT NULL,
        "UserId" bigint NOT NULL,
        "Rating" integer NOT NULL,
        "Comment" character varying(2000) NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_ProductReviews" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_ProductReviews_Rating" CHECK ("Rating" BETWEEN 1 AND 5),
        CONSTRAINT "FK_ProductReviews_Products_ProductId" FOREIGN KEY ("ProductId") REFERENCES "Products" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_ProductReviews_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261024014854_AddProductReviews') THEN
    CREATE INDEX "IX_ProductReviews_ProductId_CreatedAt" ON "ProductReviews" ("ProductId", "CreatedAt");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261024014854_AddProductReviews') THEN
    CREATE UNIQUE INDEX "IX_ProductReviews_UserId_ProductId" ON "ProductReviews" ("UserId", "ProductId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261024014854_AddProductReviews') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
